import{_ as o,l as s,o as e,c as l,v as r,p as f,x as t,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"DiffServ","description":"","frontmatter":{"title":"DiffServ","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/diffserv-qos.md","filePath":"cs/diffserv-qos.md","lastUpdated":1789023840000}'),E={name:"cs/diffserv-qos.md"};function S(h,a,c,P,B,D){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="diffserv" tabindex="-1">DiffServ <a class="header-anchor" href="#diffserv" aria-label="Permalink to &quot;DiffServ&quot;">​</a></h1><div class="epigraph"><p>DSCP 把包分到少量行为聚集，每跳 PHB（EF/AF/BE）执行；可扩展，但不在互联网上承诺端到端预留。</p><footer>—— 据 RFC 2474 / 2475 DiffServ；RFC 3246 EF；RFC 2597 AF 整理</footer></div><p><a href="/cs/wfq-fair-queue">WFQ</a> 每流不扩展。<a href="/cs/token-bucket-shaping">令牌桶</a> 可按类。<a href="/cs/token-bucket-shaping">上一课</a> 留下着色。缺口是 <strong>DiffServ 架构</strong>：标记、PHB、边界信任。本课不把 TSO 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IntServ/RSVP 每流预留在核心炸状态。DiffServ：边缘分类打 DSCP，核心只看 6 比特做 EF（低延迟）、AF（分档丢弃）、BE。无端到端硬合同，除非域内 SLA。与 5G 切片对照：切片是硬隔离实例，DSCP 是软着色。PFC 用 802.1p，要在边缘映射到 DSCP。</p><p>不要把 EF 写成 URLLC 保证：没有资源预留则 EF 也会挤。</p><p><span class="marginnote">RFC 2475 框架。核心「简」是可扩展理由。本课不把 64 个码点背完。</span></p><h3 id="域内着色" tabindex="-1">域内着色 <a class="header-anchor" href="#域内着色" aria-label="Permalink to &quot;域内着色&quot;">​</a></h3><p>少量 PHB 可扩展，无全球预留。IXP 常重标记。EF 无资源也会挤。主机乱打 EF 会被边缘改写。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：边缘分类+桶 → DSCP → 核心 PHB。对照 EVPN/QoS：租户类在覆盖内外要映射。IXP 通常不信你的 DSCP，会重置。</p>',11)),(e(),f(p,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E8%BE%B9%E7%BC%98%E5%88%86%E7%B1%BB%E6%95%B4%E5%BD%A2%22%5D%20--%3E%20DS%5B%22DSCP%22%5D%0A%20%20DS%20--%3E%20PHB%5B%22%E6%AF%8F%E8%B7%B3%20EF%2FAF%2FBE%22%5D%0A%20%20UNTRUST%5B%22%E4%B8%8D%E4%BF%A1%E4%BB%BB%E5%9F%9F%22%5D%20--%3E%20RE%5B%22%E9%87%8D%E6%A0%87%E8%AE%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AQM 可按 AF 颜色丢。ECN 与 DSCP 正交（ECN 用 TOS 低 2 位历史纠缠，实现要小心）。BGP 不传 DSCP 政策。RoCE 依赖边缘信任的优先级，跨域失效。</p><p>与 Saltzer：DiffServ 是性能，不是正确性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RSVP-TE 与 DiffServ-TE 的全部。TSO/LRO 是下一课。后课默认：公网尽力而为；DSCP 在单一信任域内有意义。</p><p>主机随意打 EF 会被边缘改写。</p><p>上一课留下的缺口在本课收口；「DiffServ」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/tso-lro">TSO / LRO</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>少量 PHB 换可扩展 QoS。</li><li>合同在域边界，不在全球。</li><li>与切片、PFC 映射但不等价。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2474/2475；RFC 3246。</li></ul>',10))])}const C=o(E,[["render",S]]);export{F as __pageData,C as default};
